import json,os,math
from pathlib import Path
from PIL import Image
E=Path('experiments/main-orc-combat-recovery-v7/rear-r');plan=json.loads((E/'plan.json').read_text());logs=json.loads((E/'author-result.json').read_text());data={};flash={}
for k,v in plan.items():
 data[k]={}
 for label,base in [('before',Path(v['source'])),('after',Path(v['dest']))]:
  c=json.loads((base/'clip.json').read_text());data[k][label]=[{'png':os.path.relpath(f['png'],E).replace('\\','/'),'body':os.path.relpath(f['layers']['body']['png'],E).replace('\\','/'),'duration':f['durationMs'],'phase':f['phase']} for f in c['frames']]
 flash[k]={'bodyNeutralWhitePixelsV6':0,'remainingBrightExteriorAfter':[],'itemContourCoordinates':[]}
 for i,f in enumerate(json.loads((Path(v['dest'])/'clip.json').read_text())['frames']):
  im=Image.open(f['png']).convert('RGBA');bright=[]
  for y in range(1,255):
   for x in range(1,255):
    r,g,b,a=im.getpixel((x,y))
    if a and min(r,g,b)>=140 and max(r,g,b)-min(r,g,b)<28 and any(im.getpixel((x+dx,y+dy))[3]==0 for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]):bright.append([x,y])
  flash[k]['remainingBrightExteriorAfter'].append({'frame':i,'coordinates':bright})
  flash[k]['itemContourCoordinates'].append({'frame':i,'edits':[e for e in logs[k]['frames'][i]['contourEdits'] if e['layer']!='body']})
(E/'flash-audit.json').write_text(json.dumps(flash,indent=2))
html='''<!doctype html><meta charset="utf-8"><title>Orc V1 V7 back_r — revisão</title><style>body{background:#1a1d24;color:#dce1e8;font:16px system-ui;margin:24px}button,select,input{margin:6px;padding:7px}header{position:sticky;top:0;background:#1a1d24;z-index:2}section{display:flex;gap:24px;flex-wrap:wrap;margin-bottom:25px}article{background:#292e38;padding:12px}canvas,img{image-rendering:pixelated;background:repeating-conic-gradient(#343943 0% 25%,#30343b 0% 50%) 50%/16px 16px}canvas{width:256px;height:256px}h2{margin-top:35px}.evidence img{width:320px;height:320px}a{color:#8bc5ff}</style><h1>Orc V1 · back_r · V7</h1><p>V7_BACK_R_REFINED · TECHNICALLY_COMPLETE · VISUAL_REVIEW_REQUIRED · PENDING_CREATOR</p><p><a href="report.md">Relatório</a> · <a href="audit.md">Auditoria</a> · <a href="grip-metrics.json">Medições palma/cabo</a>. Antes = V6 rejeitado. Reprodução repete somente para inspeção.</p><header><button id="play">Pausar</button><button id="prev">◀ Quadro</button><button id="next">Quadro ▶</button><select id="speed"><option value="1">1× normal</option><option value="0.5">0,5× lenta</option></select><select id="zoom"><option value="1">1× · composto256 / corpo128 na região central</option><option value="0.5">Tático · corpo64</option><option value="2">Zoom 2×</option><option value="4">Zoom 4×</option></select><label><input type="checkbox" id="body">body-only</label><input id="frame" type="range" min="0" max="11" value="0"><span id="state"></span></header><div id="clips"></div><h2>Pegada Axe · recortes 40×40 ampliados 16× no Aseprite</h2><p>F03/F04/F07 são índices 03/04/07; recortes centrados no respectivo assento. Deslocamentos descritos no relatório.</p><div id="evidence"></div><script>const data=DATA;let playing=true,rate=1,zoom=1,body=false,last=0;const state={Sword:{i:0,t:0},Axe:{i:0,t:0}},cache={},views=[];
for(const kind of ['Sword','Axe']){const title=document.createElement('h2');title.textContent=kind;document.querySelector('#clips').append(title);const section=document.createElement('section');document.querySelector('#clips').append(section);for(const label of ['before','after']){const a=document.createElement('article');a.innerHTML='<h3>'+ (label==='before'?'Antes · V6 rejeitado':'Depois · V7 candidato')+'</h3>';const c=document.createElement('canvas');c.width=c.height=256;a.append(c);section.append(a);views.push({kind,label,c});for(const f of data[kind][label])for(const key of ['png','body']){if(!cache[f[key]]){const im=new Image();im.src=f[key];cache[f[key]]=im}}}}
window.ready=Promise.all(Object.values(cache).map(im=>im.decode())).then(()=>{window.loaded=true;draw()});function draw(){for(const v of views){const f=data[v.kind][v.label][state[v.kind].i],ctx=v.c.getContext('2d');ctx.clearRect(0,0,256,256);ctx.imageSmoothingEnabled=false;ctx.drawImage(cache[f[body?'body':'png']],0,0);v.c.style.width=v.c.style.height=(256*zoom)+'px';v.c.dataset.frame=state[v.kind].i;v.c.dataset.source=f[body?'body':'png']}document.querySelector('#state').textContent=Object.entries(state).map(([k,v])=>k+' F'+String(v.i).padStart(2,'0')+' '+data[k].after[v.i].phase).join(' · ');document.querySelector('#frame').value=state.Axe.i}
function setFrame(i){playing=false;document.querySelector('#play').textContent='Reproduzir';for(const k in state){state[k].i=(i+12)%12;state[k].t=0}draw()}
document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pausar':'Reproduzir'};document.querySelector('#prev').onclick=()=>setFrame(state.Axe.i-1);document.querySelector('#next').onclick=()=>setFrame(state.Axe.i+1);document.querySelector('#frame').oninput=e=>setFrame(+e.target.value);document.querySelector('#speed').onchange=e=>{rate=+e.target.value};document.querySelector('#zoom').onchange=e=>{zoom=+e.target.value;draw()};document.querySelector('#body').onchange=e=>{body=e.target.checked;draw()};function tick(t){const dt=last?Math.min(t-last,100):0;last=t;if(playing&&window.loaded){for(const k in state){const s=state[k];s.t+=dt*rate;while(s.t>=data[k].after[s.i].duration){s.t-=data[k].after[s.i].duration;s.i=(s.i+1)%12}}draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);
for(const i of ['03','04','07']){const h=document.createElement('h3');h.textContent='Axe F'+i;document.querySelector('#evidence').append(h);const s=document.createElement('section');s.className='evidence';for(const when of ['before','after']){const a=document.createElement('article');a.innerHTML='<p>'+(when==='before'?'Antes':'Depois')+'</p><a href="grip-'+i+'-'+when+'.png"><img src="grip-'+i+'-'+when+'.png" alt="F'+i+' '+when+'"></a>';s.append(a)}document.querySelector('#evidence').append(s)}
</script>'''.replace('DATA',json.dumps(data))
(E/'preview.html').write_text(html,encoding='utf-8')
print('preview and flash audit written')
